export function render(container: HTMLElement) {
  container.innerHTML = `
    <div class="header">
      <h1>Chess Game</h1>
      <div class="controls">
        <button id="startBtn" class="btn primary">Start</button>
        <select id="difficultySelect" class="btn secondary">
          <option value="1">Easy</option>
          <option value="2" selected>Medium</option>
          <option value="3">Hard</option>
        </select>
      </div>
    </div>
    <div class="board" id="board"></div>
    <div class="status">
      <div id="turnDisplay">White's turn</div>
      <div id="gameStateDisplay">Game in progress</div>
      <div id="movesDisplay"></div>
    </div>
  `;

  const boardEl = document.getElementById('board') as HTMLElement;
  const startBtn = document.getElementById('startBtn') as HTMLButtonElement;
  const difficultySelect = document.getElementById('difficultySelect') as HTMLSelectElement;

  let game: Game | null = null;
  let turn: 'white' | 'black' = 'white';
  let moves: Move[] = [];
  let capturedPieces: { type: PieceType; color: 'white' | 'black' }[] = [];

  const DIFFICULTY_MAP = { 1: 3, 2: 5, 3: 7 };

  function createBoard() {
    const squares = Array(8).fill(null).map((_, i) => Array(8).fill(null));
    const piecePromotions = { 'white': 'q', 'black': 'Q' };

    for (let rank = 0; rank < 8; rank++) {
      for (let file = 0; file < 8; file++) {
        const square = { rank: 7 - rank, file };
        const isWhite = (rank < 3) || (rank >= 4 && (file === 0 || file === 7));
        const piece = getStartingPiece(square, isWhite);

        if (piece) {
          squares[rank][file] = { piece, square, color: isWhite ? 'white' : 'black' };
        }
      }
    }

    // Place pawns
    for (let rank = 0; rank < 8; rank++) {
      for (let file = 0; file < 8; file++) {
        if (squares[rank][file] && squares[rank][file].piece === 'pawn') {
          const square = squares[rank][file].square;
          const promotionRank = rank === 0 ? 7 : 0;
          if (Math.abs(square.rank - promotionRank) === 1 && square.piece === 'pawn') {
            squares[promotionRank][file] = { piece: piecePromotions[squares[promotionRank][file].color], square: { rank: promotionRank, file }, color: squares[promotionRank][file].color };
            squares[rank][file] = null;
          }
        }
      }
    }

    return squares;
  }

  function getStartingPiece(square: { rank: number; file: number }, isWhite: boolean) {
    if (square.rank === 0 && isWhite) return 'rook';
    if (square.rank === 1 && isWhite) return 'knight';
    if (square.rank === 2 && isWhite) return 'bishop';
    if (square.rank === 7 && !isWhite) return 'rook';
    if (square.rank === 6 && !isWhite) return 'knight';
    if (square.rank === 5 && !isWhite) return 'bishop';
    if (square.rank === 0 && !isWhite) return 'king';
    if (square.rank === 7 && !isWhite) return 'queen';
    if (square.rank === 0 && isWhite) return 'queen';
    return 'pawn';
  }

  function renderBoard(squares: Square[][]): void {
    const board = document.createElement('div');
    board.className = 'chess-board';
    boardEl.innerHTML = '';
    boardEl.appendChild(board);

    for (let rank = 0; rank < 8; rank++) {
      for (let file = 0; file < 8; file++) {
        const square = { rank, file };
        const isWhite = (rank + file) % 2 === 0;
        const div = document.createElement('div');
        div.className = `square ${isWhite ? 'light' : 'dark'}`;
        div.style.gridRow = (7 - rank).toString();
        div.style.gridColumn = file.toString();

        if (squares[rank][file]) {
          const { piece, square, color } = squares[rank][file];
          const pieceEl = document.createElement('div');
          pieceEl.className = `piece ${color}-${piece}`;
          pieceEl.style.gridRow = (7 - square.rank).toString();
          pieceEl.style.gridColumn = square.file.toString();
          div.appendChild(pieceEl);
        }

        div.addEventListener('click', () => {
          if (game && turn === color) {
            const rank = parseInt(div.style.gridRow.split('-')[1]);
            const file = parseInt(div.style.gridColumn);
            const move = { from: { rank, file }, to: { rank: 7 - rank, file } };
            const result = makeMove(move);
            if (result) {
              const promotionRank = result.to.rank === 0 ? 7 : 0;
              if (result.piece === 'pawn' && promotionRank !== 0) {
                const promotion = prompt('Promote pawn to queen/rook/knight/bishop (q/r/n/b)');
                if (promotion) {
                  const newPiece = { piece: promotion.toLowerCase(), square: result.to, color };
                  const newMove = { from: result.from, to: result.to, piece: newPiece };
                  moves.push(newMove);
                  squares[result.to.rank][result.to.file] = newPiece;
                  squares[result.from.rank][result.from.file] = null;
                  game = null;
                  turn = 'white';
                  renderBoard(squares);
                  return;
                }
              }
              moves.push(result);
              game = null;
              turn = turn === 'white' ? 'black' : 'white';
              renderBoard(squares);
              updateStatus();
            }
          }
        });

        board.appendChild(div);
      }
    }
  }

  function makeMove(move: Move): Move | null {
    if (!game) {
      game = {
        id: Date.now().toString(),
        pieces: [],
        moves: [],
        capturedPieces: [],
        turn: 'white',
        history: [],
        board: createBoard(),
      };
    }

    const from = move.from;
    const to = move.to;
    const piece = game.board[from.rank][from.file];
    if (!piece || piece.color !== turn) return null;

    const captured = game.board[to.rank][to.file];
    if (captured) {
      capturedPieces.push({ type: captured.piece, color: captured.color });
      game.board[to.rank][to.file] = null;
    }

    game.board[to.rank][to.file] = piece;
    game.board[from.rank][from.file] = null;
    moves.push(move);
    game.turn = turn === 'white' ? 'black' : 'white';
    game.history.push(move);

    return move;
  }

