    this.state.capturedPieces.push(piece);
  }

  reset(): void {
    this.state = {
      board: Array.from({ length: 8 }, () => Array(8).fill(0)),
      turn: 1,
      capturedPieces: [],
      moveHistory: [],
      currentPlayer: 'white',
    };
  }
}
